[Expected Approach] - Using Binary SearchThis approach applies a modified version of binary search directly to the entire rotated array. At every iteration, the middle element is checked against the key. If it’s not the key, we determine whether the left half or right half is sorted by comparing values at arr[lo] and arr[mid]. If the left half is sorted and the key lies within its range, we adjust hi = mid - 1; otherwise, we shift lo = mid + 1. If the right half is sorted and the key lies within its range, we move lo = mid + 1; else, hi = mid - 1.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool search(vector<int>& arr, int key) {
    int l = 0;
    int r = arr.size() - 1;

    while (l <= r) {
        int mid = l + (r - l) / 2;

        // Found key
        if (arr[mid] == key)
            return true;

        // Handle duplicates
        if (arr[l] == arr[mid] && arr[mid] == arr[r]) {
            l++;
            r--;
            continue;
        }

        // Left half is sorted
        if (arr[l] <= arr[mid]) {

            // Check if key is in left half
            if (arr[l] <= key && key < arr[mid])
                r = mid - 1;
            else
                l = mid + 1;
        }

        // Right half is sorted
        else {
            // Check if key is in right half
            if (arr[mid] < key && key <= arr[r])
                l = mid + 1;
            else
                r = mid - 1;
        }
    }

    return false;
}

int main() {
    vector<int> arr = {3, 3, 3, 1, 2, 3};
    int key = 3;

    if(search(arr, key))
        cout<<"true"<<endl;
    else
        cout<<"false"<<endl;

    return 0;
}


